#include <stdbool.h>

#define MAXN 300000

typedef struct {
    long long u, v;
} Point;

Point p[MAXN];
int n;
long long minU, maxU, minV, maxV;

bool can(long long D) {
    for (int c = 0; c < 4; ++c) {
        long long lx, rx, ly, ry;

        if (c < 2) {
            lx = minU;
            rx = minU + D;
        } else {
            lx = maxU - D;
            rx = maxU;
        }

        if ((c & 1) == 0) {
            ly = minV;
            ry = minV + D;
        } else {
            ly = maxV - D;
            ry = maxV;
        }

        int any = 0;
        long long rminU = 0, rmaxU = 0, rminV = 0, rmaxV = 0;

        for (int i = 0; i < n; ++i) {
            long long u = p[i].u;
            long long v = p[i].v;

            if (u >= lx && u <= rx && v >= ly && v <= ry) continue;

            if (!any) {
                any = 1;
                rminU = rmaxU = u;
                rminV = rmaxV = v;
            } else {
                if (u < rminU) rminU = u;
                if (u > rmaxU) rmaxU = u;
                if (v < rminV) rminV = v;
                if (v > rmaxV) rmaxV = v;
            }
        }

        if (!any) return true;
        if (rmaxU - rminU <= D && rmaxV - rminV <= D) return true;
    }

    return false;
}

int main() {
    scanf("%d", &n);

    for (int i = 0; i < n; ++i) {
        scanf("%lld", &p[i].u);
    }

    for (int i = 0; i < n; ++i) {
        long long y;
        scanf("%lld", &y);

        long long x = p[i].u;
        p[i].u = x + y;
        p[i].v = x - y;
    }

    minU = maxU = p[0].u;
    minV = maxV = p[0].v;

    for (int i = 1; i < n; ++i) {
        if (p[i].u < minU) minU = p[i].u;
        if (p[i].u > maxU) maxU = p[i].u;
        if (p[i].v < minV) minV = p[i].v;
        if (p[i].v > maxV) maxV = p[i].v;
    }

    long long hi = maxU - minU;
    long long h2 = maxV - minV;
    if (h2 > hi) hi = h2;

    long long lo = -1;

    while (hi - lo > 1) {
        long long mid = lo + (hi - lo) / 2;

        if (can(mid)) hi = mid;
        else lo = mid;
    }

    printf("%lld\n", hi);

    return 0;
}
